//! Shared wire format for the Sirus virtual ISA. The compiler and the injected
//! runtime include this exact module so they can never disagree about operand
//! roles or physical register numbering.

/// Number of virtual registers available to generated bytecode.
pub const VM_REGISTERS: usize = 64;

/// Size of the byte-addressable virtual stack/memory.
pub const VM_MEMORY_SIZE: usize = 4096;

/// Initial virtual stack pointer. The stack grows down, matching x86-64.
pub const VM_STACK_TOP: u64 = 4080;

/// Maximum number of aliases assigned to one semantic operation.
pub const ALIASES_PER_SEMANTIC: usize = 4;

/// Number of semantic operations in the virtual ISA.
pub const SEMANTIC_COUNT: usize = 44;

/// Maximum number of fields in one encoded instruction.
pub const MAX_OPERANDS: usize = 4;

/// Maximum encoded instruction size in bytes.
pub const MAX_INSTRUCTION_BYTES: usize = 1 + (MAX_OPERANDS * 8);

/// Marker used for unassigned opcode bytes.
pub const INVALID_OPCODE: u8 = 0xFF;

/// A field in the canonical operand layout.
pub const ROLE_NONE: u8 = 0;
/// A virtual register operand.
pub const ROLE_REG: u8 = 1;
/// A 64-bit immediate operand.
pub const ROLE_IMM: u8 = 2;

/// x86-64 architectural registers live in fixed logical slots.
pub const REG_RAX: u8 = 0;
/// `RCX`.
pub const REG_RCX: u8 = 1;
/// `RDX`.
pub const REG_RDX: u8 = 2;
/// `RBX`.
pub const REG_RBX: u8 = 3;
/// `RSP`.
pub const REG_RSP: u8 = 4;
/// `RBP`.
pub const REG_RBP: u8 = 5;
/// `RSI`.
pub const REG_RSI: u8 = 6;
/// `RDI`.
pub const REG_RDI: u8 = 7;
/// `R8`.
pub const REG_R8: u8 = 8;
/// `R9`.
pub const REG_R9: u8 = 9;
/// `R10`.
pub const REG_R10: u8 = 10;
/// `R11`.
pub const REG_R11: u8 = 11;
/// `R12`.
pub const REG_R12: u8 = 12;
/// `R13`.
pub const REG_R13: u8 = 13;
/// `R14`.
pub const REG_R14: u8 = 14;
/// `R15`.
pub const REG_R15: u8 = 15;
/// Zero flag, represented as 0 or 1.
pub const REG_ZF: u8 = 16;
/// Carry flag, represented as 0 or 1.
pub const REG_CF: u8 = 17;
/// Sign flag, represented as 0 or 1.
pub const REG_SF: u8 = 18;
/// Overflow flag, represented as 0 or 1.
pub const REG_OF: u8 = 19;

/// Constant zero maintained by the lifter.
pub const REG_ZERO: u8 = 20;
/// Constant one maintained by the lifter.
pub const REG_ONE: u8 = 21;
/// First compiler scratch register.
pub const REG_TEMP_BASE: u8 = 24;
/// Number of compiler scratch registers.
pub const REG_TEMP_COUNT: u8 = 36;
/// First lifter scratch register. Never live across IR statements.
pub const REG_TMP0: u8 = 60;
/// Second lifter scratch register. Never live across IR statements.
pub const REG_TMP1: u8 = 61;
/// Third lifter scratch register. Never live across IR statements.
pub const REG_TMP2: u8 = 62;
/// Fourth lifter scratch register. Never live across IR statements.
pub const REG_TMP3: u8 = 63;

/// Default instruction budget for one protected invocation.
pub const DEFAULT_FUEL: u64 = 2_000_000;

/// A canonical operand layout.
#[non_exhaustive]
#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct Format {
    /// Role of each operand, in canonical order.
    pub roles: [u8; MAX_OPERANDS],
    /// Number of active roles.
    pub len: u8,
}

impl Format {
    /// Builds a layout from up to four roles.
    #[inline]
    #[must_use]
    pub const fn new(roles: [u8; MAX_OPERANDS], len: u8) -> Self {
        Self { roles, len }
    }
}

const fn f2(a: u8, b: u8) -> Format {
    Format::new([a, b, ROLE_NONE, ROLE_NONE], 2)
}

const fn f3(a: u8, b: u8, c: u8) -> Format {
    Format::new([a, b, c, ROLE_NONE], 3)
}

const fn f4(a: u8, b: u8, c: u8, d: u8) -> Format {
    Format::new([a, b, c, d], 4)
}

const fn f1(a: u8) -> Format {
    Format::new([a, ROLE_NONE, ROLE_NONE, ROLE_NONE], 1)
}

/// Semantic opcode: no operation.
pub const SEM_NOP: u8 = 0;
/// `dst = src`.
pub const SEM_MOV_RR: u8 = 1;
/// `dst = immediate`.
pub const SEM_MOV_RI: u8 = 2;
/// `dst = dst + src`.
pub const SEM_ADD_RR: u8 = 3;
/// `dst = dst + immediate`.
pub const SEM_ADD_RI: u8 = 4;
/// `dst = dst - src`.
pub const SEM_SUB_RR: u8 = 5;
/// `dst = dst - immediate`.
pub const SEM_SUB_RI: u8 = 6;
/// `dst = dst * src`.
pub const SEM_MUL_RR: u8 = 7;
/// `dst = dst & src`.
pub const SEM_AND_RR: u8 = 8;
/// `dst = dst & immediate`.
pub const SEM_AND_RI: u8 = 9;
/// `dst = dst | src`.
pub const SEM_OR_RR: u8 = 10;
/// `dst = dst | immediate`.
pub const SEM_OR_RI: u8 = 11;
/// `dst = dst ^ src`.
pub const SEM_XOR_RR: u8 = 12;
/// `dst = dst ^ immediate`.
pub const SEM_XOR_RI: u8 = 13;
/// `dst = ~dst`.
pub const SEM_NOT_R: u8 = 14;
/// `dst = -dst`.
pub const SEM_NEG_R: u8 = 15;
/// `dst = (dst << (src & 63))`.
pub const SEM_SHL_RR: u8 = 16;
/// `dst = (dst << (immediate & 63))`.
pub const SEM_SHL_RI: u8 = 17;
/// Logical right shift by a register.
pub const SEM_SHR_RR: u8 = 18;
/// Logical right shift by an immediate.
pub const SEM_SHR_RI: u8 = 19;
/// Arithmetic right shift by a register.
pub const SEM_SAR_RR: u8 = 20;
/// Arithmetic right shift by an immediate.
pub const SEM_SAR_RI: u8 = 21;
/// Rotate left by a register.
pub const SEM_ROTL_RR: u8 = 22;
/// Rotate left by an immediate.
pub const SEM_ROTL_RI: u8 = 23;
/// Rotate right by a register.
pub const SEM_ROTR_RR: u8 = 24;
/// Rotate right by an immediate.
pub const SEM_ROTR_RI: u8 = 25;
/// `dst = (a == b)`.
pub const SEM_CMPEQ_RR: u8 = 26;
/// `dst = (a < b)` as unsigned.
pub const SEM_CMPLTU_RR: u8 = 27;
/// `dst = (a < b)` as signed.
pub const SEM_CMPLTS_RR: u8 = 28;
/// `dst = (a <= b)` as unsigned.
pub const SEM_CMPLEU_RR: u8 = 29;
/// `dst = (a <= b)` as signed.
pub const SEM_CMPLES_RR: u8 = 30;
/// `dst = cond ? a : b`; operand order is dst, cond, a, b.
pub const SEM_SELECT_RRRR: u8 = 31;
/// Load eight bits from virtual memory.
pub const SEM_LOAD8: u8 = 32;
/// Load sixteen bits from virtual memory.
pub const SEM_LOAD16: u8 = 33;
/// Load thirty-two bits from virtual memory.
pub const SEM_LOAD32: u8 = 34;
/// Load sixty-four bits from virtual memory.
pub const SEM_LOAD64: u8 = 35;
/// Store eight bits to virtual memory.
pub const SEM_STORE8: u8 = 36;
/// Store sixteen bits to virtual memory.
pub const SEM_STORE16: u8 = 37;
/// Store thirty-two bits to virtual memory.
pub const SEM_STORE32: u8 = 38;
/// Store sixty-four bits to virtual memory.
pub const SEM_STORE64: u8 = 39;
/// Unconditional state transition: `target = a ^ b`, then a canceling mix.
pub const SEM_JMP: u8 = 40;
/// Conditional state transition: `cond ? true_target : false_target`, mixed.
pub const SEM_JCC: u8 = 41;
/// Return a register to the host.
pub const SEM_RET: u8 = 42;
/// Deterministic clean halt for malformed or hostile bytecode.
pub const SEM_TRAP: u8 = 43;

/// Every semantic id in ascending order. Iterating this array avoids unchecked
/// integer casts and keeps table construction exhaustive.
pub const SEMANTIC_IDS: [u8; SEMANTIC_COUNT] = [
    SEM_NOP,
    SEM_MOV_RR,
    SEM_MOV_RI,
    SEM_ADD_RR,
    SEM_ADD_RI,
    SEM_SUB_RR,
    SEM_SUB_RI,
    SEM_MUL_RR,
    SEM_AND_RR,
    SEM_AND_RI,
    SEM_OR_RR,
    SEM_OR_RI,
    SEM_XOR_RR,
    SEM_XOR_RI,
    SEM_NOT_R,
    SEM_NEG_R,
    SEM_SHL_RR,
    SEM_SHL_RI,
    SEM_SHR_RR,
    SEM_SHR_RI,
    SEM_SAR_RR,
    SEM_SAR_RI,
    SEM_ROTL_RR,
    SEM_ROTL_RI,
    SEM_ROTR_RR,
    SEM_ROTR_RI,
    SEM_CMPEQ_RR,
    SEM_CMPLTU_RR,
    SEM_CMPLTS_RR,
    SEM_CMPLEU_RR,
    SEM_CMPLES_RR,
    SEM_SELECT_RRRR,
    SEM_LOAD8,
    SEM_LOAD16,
    SEM_LOAD32,
    SEM_LOAD64,
    SEM_STORE8,
    SEM_STORE16,
    SEM_STORE32,
    SEM_STORE64,
    SEM_JMP,
    SEM_JCC,
    SEM_RET,
    SEM_TRAP,
];

/// Returns the canonical operand layout of a semantic operation.
#[inline]
#[must_use]
pub fn format(semantic: u8) -> Option<Format> {
    match semantic {
        SEM_NOP => Some(Format::new([ROLE_NONE; MAX_OPERANDS], 0)),
        SEM_MOV_RR => Some(f2(ROLE_REG, ROLE_REG)),
        SEM_MOV_RI => Some(f2(ROLE_REG, ROLE_IMM)),
        SEM_ADD_RR | SEM_SUB_RR | SEM_MUL_RR | SEM_AND_RR | SEM_OR_RR | SEM_XOR_RR
        | SEM_SHL_RR | SEM_SHR_RR | SEM_SAR_RR | SEM_ROTL_RR | SEM_ROTR_RR => {
            Some(f2(ROLE_REG, ROLE_REG))
        }
        SEM_ADD_RI | SEM_SUB_RI | SEM_AND_RI | SEM_OR_RI | SEM_XOR_RI | SEM_SHL_RI
        | SEM_SHR_RI | SEM_SAR_RI | SEM_ROTL_RI | SEM_ROTR_RI => Some(f2(ROLE_REG, ROLE_IMM)),
        SEM_NOT_R | SEM_NEG_R | SEM_RET => Some(f1(ROLE_REG)),
        SEM_CMPEQ_RR | SEM_CMPLTU_RR | SEM_CMPLTS_RR | SEM_CMPLEU_RR | SEM_CMPLES_RR => {
            Some(f3(ROLE_REG, ROLE_REG, ROLE_REG))
        }
        SEM_SELECT_RRRR => Some(f4(ROLE_REG, ROLE_REG, ROLE_REG, ROLE_REG)),
        SEM_LOAD8 | SEM_LOAD16 | SEM_LOAD32 | SEM_LOAD64 => Some(f2(ROLE_REG, ROLE_REG)),
        SEM_STORE8 | SEM_STORE16 | SEM_STORE32 | SEM_STORE64 => Some(f2(ROLE_REG, ROLE_REG)),
        SEM_JMP => Some(f2(ROLE_IMM, ROLE_REG)),
        SEM_JCC => Some(f4(ROLE_REG, ROLE_IMM, ROLE_IMM, ROLE_REG)),
        SEM_TRAP => Some(Format::new([ROLE_NONE; MAX_OPERANDS], 0)),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::{
        format, ROLE_IMM, ROLE_REG, SEMANTIC_IDS, SEMANTIC_COUNT, SEM_ADD_RR, SEM_JCC, SEM_JMP,
        SEM_MOV_RI, SEM_SELECT_RRRR, VM_REGISTERS,
    };

    #[test]
    fn every_semantic_has_a_valid_layout() {
        let mut valid = 0_usize;
        for semantic in SEMANTIC_IDS {
            let layout = format(semantic);
            assert!(layout.is_some(), "missing format for {semantic}");
            if let Some(layout) = layout {
                assert!(usize::from(layout.len) <= 4);
                for role in layout.roles {
                    assert!(role <= ROLE_IMM);
                }
                valid += 1;
            }
        }
        assert_eq!(valid, SEMANTIC_COUNT);
    }

    #[test]
    fn register_and_immediate_roles_match() {
        assert_eq!(
            format(SEM_MOV_RI).map(|value| (value.roles, value.len)),
            Some(([ROLE_REG, ROLE_IMM, 0, 0], 2))
        );
        assert_eq!(
            format(SEM_ADD_RR).map(|value| value.len),
            Some(2)
        );
        assert_eq!(format(SEM_SELECT_RRRR).map(|value| value.len), Some(4));
    }

    #[test]
    fn transition_layouts_are_two_and_four_operands() {
        assert_eq!(format(SEM_JMP).map(|value| value.len), Some(2));
        assert_eq!(format(SEM_JCC).map(|value| value.len), Some(4));
    }

    #[test]
    fn register_file_is_large_enough() {
        assert_eq!(VM_REGISTERS, 64);
    }
}
